DO $$ BEGIN
IF current_database()<>'neondb' OR current_user<>'neondb_owner' THEN RAISE EXCEPTION 'target_identity_refused'; END IF;
IF to_regclass('public."PipelineAICallReservation"') IS NOT NULL OR EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='PipelineStageRun' AND column_name='aiClaimGeneration') THEN RAISE EXCEPTION 'unexpected_schema_drift'; END IF;
IF EXISTS(SELECT 1 FROM public."AIUsageReservation" WHERE status IN ('reserved','dispatch_unknown','pending_settlement')) THEN RAISE EXCEPTION 'unresolved_credit_work'; END IF;
IF (SELECT count(*) FROM public."_prisma_migrations" WHERE finished_at IS NULL AND rolled_back_at IS NULL)<>1 OR NOT EXISTS(SELECT 1 FROM public."_prisma_migrations" WHERE migration_name='20261013172000_add_workspace_agent_identity' AND checksum='761c693202763e71c7ee25f99e194fe010335cf902b5ed37124351a93d42e3f7' AND finished_at IS NULL AND rolled_back_at IS NULL AND applied_steps_count=0) THEN RAISE EXCEPTION 'migration_history_drift'; END IF;
END $$

DO $$ BEGIN
IF current_setting('axiom.batch_before')::jsonb<>(SELECT jsonb_build_object('runs',(SELECT jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY id),''))) FROM public."PipelineRun" t),'stages',(SELECT jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(md5((to_jsonb(t)-'aiClaimGeneration')::text),'' ORDER BY id),''))) FROM public."PipelineStageRun" t),'holds',(SELECT jsonb_build_object('rows',count(*),'digest',md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY id),''))) FROM public."AIUsageReservation" t))) THEN RAISE EXCEPTION 'existing_data_changed'; END IF;
IF (SELECT count(*) FROM public."PipelineAICallReservation")<>0 OR EXISTS(SELECT 1 FROM public."PipelineStageRun" WHERE "aiClaimGeneration" IS NOT NULL) THEN RAISE EXCEPTION 'new_storage_not_empty'; END IF;
IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='PipelineStageRun' AND column_name='aiClaimGeneration' AND data_type='text' AND is_nullable='YES' AND column_default IS NULL) THEN RAISE EXCEPTION 'claim_column_invalid'; END IF;
IF (SELECT count(*) FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname=ANY(ARRAY['PipelineAICallReservation_workspaceReservationId_key','PipelineAICallReservation_usageEventId_key','PipelineAICallReservation_externalUsageId_key','PipelineAICallReservation_runId_status_idx','PipelineAICallReservation_organizationId_workspaceReservati_key','PipelineAICallReservation_organizationId_stageRunId_phase_key','PipelineAICallReservation_organizationId_idempotencyKey_key','PipelineRun_organizationId_id_key','PipelineStageRun_runId_id_key','AIUsageReservation_organizationId_id_key']) AND i.indisvalid AND i.indisready)<>10 THEN RAISE EXCEPTION 'index_verification_failed'; END IF;
IF (SELECT count(*) FROM pg_constraint WHERE conrelid='public."PipelineAICallReservation"'::regclass AND contype='f' AND convalidated AND confdeltype='r' AND confupdtype='c')<>3 THEN RAISE EXCEPTION 'foreign_key_verification_failed'; END IF;
END $$
